package org.jboss.as.test.integration.domain.management.util;

import static org.jboss.as.controller.descriptions.ModelDescriptionConstants.RESTART_SERVERS;

import org.jboss.as.test.integration.domain.management.util.DomainLifecycleUtil;
import org.jboss.dmr.ModelNode;
import org.junit.Assert;
import org.junit.Test;

/**
 * Unit tests for {@link DomainLifecycleUtil.ReloadParameters}.
 */
public class DomainLifecycleUtilReloadParametersTest {

    /**
     * Verify that when using default ReloadParameters, the RESTART_SERVERS attribute
     * is NOT set on the operation, matching the old behavior where restartServers was
     * nullable Boolean and only set when non-null.
     *
     * The old code had:
     *   if (restartServers != null) {
     *       op.get(ModelDescriptionConstants.RESTART_SERVERS).set(restartServers);
     *   }
     * So a default reload(host) would omit restart-servers from the operation.
     *
     * The new code always sets:
     *   op.get(ModelDescriptionConstants.RESTART_SERVERS).set(parameters.restartServers);
     * which means restart-servers=true is always included, changing behavior.
     */
    @Test
    public void testDefaultReloadParametersShouldNotIncludeRestartServers() {
        DomainLifecycleUtil.ReloadParameters params = new DomainLifecycleUtil.ReloadParameters();

        // Build the operation the same way reload() does
        ModelNode op = new ModelNode();
        op.get("op").set("reload");
        op.get("admin-only").set(params.adminOnly);
        op.get(RESTART_SERVERS).set(params.restartServers);

        // In the old code, when restartServers was null, the attribute was NOT set.
        // The default reload(host) should NOT include restart-servers attribute.
        Assert.assertFalse(
            "Default ReloadParameters should not include restart-servers attribute in the operation, " +
            "matching the old behavior where it was only set when explicitly configured",
            op.hasDefined(RESTART_SERVERS)
        );
    }

    /**
     * Verify that when restart-servers is explicitly set to false, the attribute IS included.
     */
    @Test
    public void testExplicitRestartServersFalseShouldIncludeRestartServers() {
        DomainLifecycleUtil.ReloadParameters params = new DomainLifecycleUtil.ReloadParameters()
                .setRestartServers(false);

        ModelNode op = new ModelNode();
        op.get("op").set("reload");
        op.get("admin-only").set(params.adminOnly);
        op.get(RESTART_SERVERS).set(params.restartServers);

        Assert.assertTrue(
            "Explicitly set restart-servers=false should be included in the operation",
            op.hasDefined(RESTART_SERVERS)
        );
        Assert.assertFalse(op.get(RESTART_SERVERS).asBoolean());
    }

    /**
     * Verify that when restart-servers is explicitly set to true, the attribute IS included.
     */
    @Test
    public void testExplicitRestartServersTrueShouldIncludeRestartServers() {
        DomainLifecycleUtil.ReloadParameters params = new DomainLifecycleUtil.ReloadParameters()
                .setRestartServers(true);

        ModelNode op = new ModelNode();
        op.get("op").set("reload");
        op.get("admin-only").set(params.adminOnly);
        op.get(RESTART_SERVERS).set(params.restartServers);

        Assert.assertTrue(
            "Explicitly set restart-servers=true should be included in the operation",
            op.hasDefined(RESTART_SERVERS)
        );
        Assert.assertTrue(op.get(RESTART_SERVERS).asBoolean());
    }
}

